"use strict";
/* ================= THE OUTLINE: each hall as a course =================
   Chapters in teaching order. Each chapter has:
     id      stable slug (never reuse or rename: use it for any per-chapter state, not the array index)
     t, aim  title and one-line aim
     master  3 to 5 precise objectives: what you must be able to do, with the fact stated
     signs / tech / pres / sounds / cases / scen / maps / tools / labs / go   linked items (ids checked by check.js)
     cards   OPTIONAL extra card ids for the chapter session; an entry ending in "*" is a prefix (e.g. "cn:*", "dv:*")
     trap, pearl
     red     OPTIONAL red flags line: what makes you act now
     say     OPTIONAL "say it like this": a line to the patient, or a handover / documentation line
     src     OPTIONAL sources for the facts in the chapter
   Hall order and membership belong to 03-world.js; this file owns only the chapters. */
const OUTLINE={
table:[
 {id:"table-endbed",t:"The end of the bed",aim:"Decide in thirty seconds how sick the patient is.",
  master:["Judge four things before touching: colour, work of breathing, conscious level, and posture or behaviour","Count the respiratory rate for a full 60 seconds without the patient noticing","Say what each smell tells you: ketones (DKA), uraemic fetor, fetor hepaticus, alcohol, melaena","Note habitus with a tape measure: waist circumference adds to BMI"],
  signs:["resp-rate","cyanosis","kussmaul-breathing","bmi-waist"],tools:["bmi"],go:[["learn/module/gen","General survey and vital signs"]],cards:["f:gen:0"],
  trap:"Being reassured by a normal oxygen saturation in a patient breathing at 30 a minute.",pearl:"Respiratory rate is the vital sign most often guessed and one of the earliest to change before deterioration.",
  red:"A respiratory rate of 25 or more, new confusion, or a systolic pressure of 90 or less each score 3 in NEWS2 on their own: get a senior review now.",
  say:"Respiratory rate 28, counted over a full minute; using accessory muscles and speaking in short phrases.",
  src:"RCP NEWS2 (2017); Macleod's Clinical Examination 15e, ch 3"},
 {id:"table-history",t:"The history as a hypothesis",aim:"Take a history that tests diagnoses instead of collecting words.",
  master:["Open with an open question and let the patient finish the opening statement","Use SOCRATES for pain and ask ideas, concerns and expectations","Take an occupational history from every working adult: the job, the exposures, since when, and whether it is better on days off","Build a differential and a rough pretest probability before you examine, then use findings with known likelihood ratios to move it"],
  pres:["occ","ftw","nsi","fever"],tools:["post-test-probability"],go:[["learn/frames","History frameworks"],["practice/er","ER cases"]],
  trap:"Asking closed questions too early, then examining everything.",pearl:"In occupational medicine the job is often the diagnosis: ask what they do, with what, and since when.",
  say:"Before we go on: what were you worried this might be?",
  src:"Calgary-Cambridge guide; Macleod's 15e, ch 1 and 2; McGee, Evidence-Based Physical Diagnosis 5e, ch 2"},
 {id:"table-vitals",t:"Vital signs, read together",aim:"Turn numbers into a physiology: perfused or not, compensating or failing.",
  master:["Calculate the shock index (over 0.9 is abnormal) and know when it misleads: beta-blockers, pacing, old age, pregnancy","For blood loss: 2 minutes supine, then the pulse after 1 minute standing; a rise of 30/min or more, or dizziness that stops the patient standing, is positive","For orthostatic hypotension: 5 minutes supine, then BP at 1 and 3 minutes standing; a fall of 20 mmHg systolic or 10 mmHg diastolic is positive","Score NEWS2 to detect deterioration; use qSOFA only as a prognostic prompt, never as a sepsis screen","Calculate MAP and know the usual target in septic shock: 65 mmHg"],
  signs:["shock-index","postural","cap-refill","temp","passive-leg-mottling","qsofa","news2"],tools:["news2","qsofa","shock-index","map"],maps:["sepsis-recognition"],labs:["lactate"],cards:["f:gen:1","f:gen:2","f:gen:3"],
  trap:"A 'normal' blood pressure in a young bleeding patient: hypotension often appears only after about 30% of the blood volume is lost.",pearl:"Tachycardia without fever or pain is hypovolaemia, sepsis, PE or arrhythmia until shown otherwise.",
  red:"NEWS2 of 7 or more: emergency response. A score of 3 in any single parameter: urgent review.",
  src:"McGee 5e, ch 15; Freeman et al., Clin Auton Res 2011 (orthostatic hypotension consensus); RCP NEWS2 (2017); Surviving Sepsis Campaign 2021; ATLS"},
 {id:"table-volume",t:"Volume status",aim:"Synthesise hydration from several weak signs, never one.",
  master:["Combine the postural pulse, a dry axilla, mucous membranes, JVP, urine output, weight change and the urea","Know that skin turgor is useful in children, not in adults","Look for overload as carefully as for depletion: JVP, oedema, crackles","Calculate maintenance fluid for a child with Holliday–Segar (4-2-1) and use isotonic fluid"],
  signs:["dry-axilla","skin-turgor","postural","jvp"],tools:["holliday-segar"],labs:["u-and-e"],
  trap:"Relying on skin turgor in the elderly.",pearl:"A dry axilla raises the likelihood of hypovolaemia; a moist one barely lowers it.",
  src:"McGee 5e, ch 11; NICE NG29 (IV fluids in children)"},
 {id:"table-periphery",t:"The hands, the face, the eyes",aim:"Read systemic disease from the periphery before you reach the organ.",
  master:["Look at the hands first: nails, palms, tremor, joints, skin","Detect clubbing: loss of the Schamroth window and a nail-fold angle over 180°","Look for pallor in the conjunctival rim, not the skin","See icterus at the sclera in natural light; it appears at a bilirubin of about 40 to 50 µmol/L"],
  signs:["clubbing","conj-pallor","jaundice","acanthosis"],cards:["f:gen:4","f:gen:5"],
  trap:"Calling jaundice under yellow artificial light.",pearl:"New clubbing in an adult: lung cancer, fibrotic lung disease, bronchiectasis or empyema, cyanotic heart disease, endocarditis, cirrhosis, IBD. COPD alone does not cause clubbing: look for a cancer.",
  src:"Talley and O'Connor, Clinical Examination 9e (hands); Myers and Farquhar, JAMA 2001 (clubbing); McGee 5e"},
 {id:"table-injured",t:"The injured patient",aim:"Run a primary survey in the order that kills first.",
  master:["Work xABCDE: stop exsanguinating external bleeding first, then the airway with cervical spine protection","In B, look, feel, percuss and listen for tension pneumothorax, open pneumothorax, flail chest and massive haemothorax","In C, look for blood on the floor and four more: chest, abdomen, pelvis and long bones","In D and E, record GCS, pupils and glucose; expose, log roll and keep the patient warm","Take AMPLE (allergies, medicines, past illness and pregnancy, last meal, events) plus tetanus status and the time of injury"],
  pres:["trauma","envenom"],signs:["gcs","tension-ptx","tracheal-deviation","battle"],tools:["gcs","shock-index","parkland"],scen:["tamp"],
  trap:"Being drawn to the obvious limb injury while the patient bleeds into the chest or pelvis.",pearl:"Tachycardia, cool peripheries and anxiety come before hypotension; in the elderly or on beta-blockers even these may be absent.",
  red:"Catastrophic bleeding, a threatened airway, absent breath sounds with hypotension, a falling GCS or a new dilated pupil: act before you finish the survey.",
  say:"ATMIST handover: Age, Time of injury, Mechanism, Injuries found, Signs (vital signs), Treatment given.",
  src:"ATLS 11th ed (American College of Surgeons, 2025); NICE NG39 (major trauma); UKHSA Green Book ch 30 (tetanus)"},
 {id:"table-confused",t:"The confused patient",aim:"Recognise delirium, find its cause, and decide about capacity.",
  master:["Screen with the 4AT: alertness, AMT4, months of the year backwards, and acute change or fluctuation; a score of 4 or more suggests delirium","Recognise hypoactive delirium: the quiet, sleepy patient is the one most often missed","Check the glucose first, then look for the causes: infection, drugs and withdrawal, sodium, calcium, hypoxia or hypercapnia, retention, constipation, pain, stroke","Get a collateral history of the baseline: delirium is acute and fluctuating, dementia is gradual","Assess capacity for the decision in front of you: can the patient understand, retain, weigh and communicate it?"],
  signs:["four-at","gcs","asterixis","temp"],pres:["heat","poison"],tools:["four-at","gcs","corrected-na","anion-gap","osmolar-gap","winters","delta-ratio"],labs:["glucose-hba1c","u-and-e","blood-gas","vbg","urinalysis"],cards:["f:neuro:2"],
  trap:"Calling hypoactive delirium depression, or blaming new confusion on known dementia.",pearl:"A patient with dementia who is suddenly worse has delirium until proved otherwise.",
  red:"Confusion with fever and headache or a stiff neck, with focal signs, with a low glucose, or after a head injury on an anticoagulant.",
  say:"To test capacity for this decision: Tell me in your own words what we think is wrong and what we suggest. What could happen if you do not have it?",
  src:"SIGN 157 (delirium, 2019); NICE CG103; Tieges et al., Age Ageing 2021 (4AT accuracy); Mental Capacity Act 2005 Code of Practice (follow the law where you work)"},
 {id:"table-rash",t:"The rash that cannot wait",aim:"Recognise the non-blanching rash and act within minutes.",
  master:["Do the glass test: a rash that does not fade under the glass is petechial or purpuric","Suspected meningococcal disease outside hospital: give IV or IM benzylpenicillin if it will not delay transfer: 1.2 g for adults and children aged 10 or over, 600 mg aged 1 to 9, 300 mg under 1","Use the NICE traffic-light system to judge a febrile child under 5","Know the other causes of petechiae: low platelets, leukaemia, vasculitis, and harmless petechiae above the nipple line after coughing or vomiting"],
  signs:["purpura-glass","temp","cap-refill"],pres:["febchild"],maps:["sepsis-recognition"],cards:["f:gen:6","f:derm:4","dc:meningococcal","dc:petechiae-plt","dv:13","dv:14"],
  trap:"Waiting for a rash before suspecting meningococcal sepsis; it may come late or never.",pearl:"Cold hands and feet, leg pain and abnormal skin colour come before the rash in children.",
  red:"Fever with any non-blanching rash, or an ill-looking child: treat and transfer now.",
  say:"If a rash appears that does not fade under a glass, or your child gets worse, come straight back or call an ambulance.",
  src:"NICE NG240 (bacterial meningitis and meningococcal disease, 2024); NICE NG143 (fever in under 5s); Thompson et al., Lancet 2006"},
 {id:"table-gals",t:"Screening the joints",aim:"Screen the musculoskeletal system in two minutes.",
  master:["Ask the three GALS questions: pain or stiffness in muscles, joints or back; dressing without difficulty; managing stairs","Perform GALS: gait, arms, legs, spine, and record it","Recognise inflammatory arthritis: morning stiffness over 30 minutes, small-joint swelling, a positive MCP squeeze","Know when a screen becomes a regional examination"],
  signs:["gals"],cards:["f:msk:6"],go:[["learn/region/hip","Hip"],["learn/region/knee","Knee"]],
  trap:"Skipping the gait.",pearl:"Persistent synovitis needs urgent rheumatology referral even when the rheumatoid factor is negative.",
  src:"Doherty et al., Ann Rheum Dis 1992 (GALS); NICE NG100 (rheumatoid arthritis)"}
],
heart:[
 {id:"heart-pulse",t:"The pulse",aim:"Feel rate, rhythm, volume and character, and know which artery tells you what.",
  master:["Count the radial for 30 seconds if regular; for a full minute, and apically, if irregular","Judge character at the carotid: slow-rising (AS), collapsing (AR), bisferiens","Feel for radio-radial and radio-femoral delay: coarctation, dissection, subclavian stenosis","After an irregular pulse: a 12-lead ECG, then stroke risk (CHA₂DS₂-VA) and bleeding risk"],
  signs:["irregular-pulse","carotid-upstroke","radio-femoral"],tools:["cha2ds2va","hasbled"],go:[["learn/module/cvs","The cardiovascular examination"],["learn/hall/vessels","Blood pressure (Hall of Vessels)"]],cards:["f:cvs:6"],
  trap:"Judging character at the radial.",pearl:"A regular pulse makes atrial fibrillation unlikely at that moment; an irregularly irregular one needs an ECG, and paroxysmal AF needs longer monitoring.",
  src:"Talley and O'Connor 9e, cardiovascular chapter; McGee 5e; ESC AF guidelines 2024"},
 {id:"heart-jvp",t:"The jugular venous pressure",aim:"See the right atrium in the neck and tell it from the carotid.",
  master:["Sit the patient at 45° with the head turned slightly away, use tangential light and find the double waveform","Measure the vertical height above the sternal angle: over 3 cm is raised; conventionally add 5 cm for the right atrial pressure","Perform abdominojugular reflux: a sustained rise during 10 to 15 seconds of abdominal pressure","Interpret Kussmaul's sign (a rise on inspiration): constriction, restriction, RV infarction"],
  signs:["jvp","ajr","kussmaul-sign"],maps:["jvp-physiology"],cards:["a:chest:angle","a:neck:ijv"],
  trap:"Calling the carotid the JVP: the JVP is not palpable, has two waves, falls on inspiration and can be occluded by light pressure.",pearl:"A raised JVP with clear lungs and hypotension: tamponade, tension pneumothorax, massive PE or RV infarction.",
  src:"McGee 5e, ch 36; Talley and O'Connor 9e"},
 {id:"heart-palpate",t:"Inspection and palpation",aim:"Find the apex and feel for heaves and thrills before you listen.",
  master:["Locate the apex, turning the patient to the left if needed","Distinguish a sustained (pressure) from a displaced, diffuse (volume) apex","Feel for a parasternal heave and for thrills (a palpable murmur is grade 4 or more)"],
  signs:["apex-displaced","heave-thrill","cardiac-dullness"],cards:["a:chest:apex"],
  trap:"Calling an apex displaced in a patient who is lying rotated.",pearl:"An apex beat lateral to the midclavicular line is one of the better bedside signs of a low ejection fraction.",
  src:"McGee 5e; Talley and O'Connor 9e"},
 {id:"heart-sounds",t:"Heart sounds",aim:"Hear S1, S2, its splitting, and the extra sounds.",
  master:["Time S1 with the carotid pulse","Hear physiological, wide, fixed and reversed splitting and say what causes each","Hear S3 (ken-TUC-ky) and S4 (TEN-nes-see) with the bell, lightly applied","Place the listening areas and know they reflect where sound travels, not where valves sit"],
  signs:["s3","s4","a2-soft"],sounds:["normal","physio-split","wide-split","fixed-split","paradox-split","s3","s4","ec"],go:[["sounds/map","Where to listen, and why"]],cards:["ar:*"],
  trap:"Listening with the diaphragm for S3 and S4: they are low-pitched; use the bell lightly.",pearl:"An S3 can be normal under about 40 and in pregnancy; in an older breathless patient it means a high filling pressure.",
  src:"McGee 5e, ch 39; Talley and O'Connor 9e"},
 {id:"heart-murmurs",t:"Murmurs",aim:"Describe any murmur by timing, site, radiation, grade and manoeuvres.",
  master:["Time against the carotid; describe shape and grade (1 to 6)","Use manoeuvres: inspiration (right-sided louder), sitting forward in expiration (AR), left lateral (MS), Valsalva and handgrip","Differentiate AS, MR, AR, MS, HOCM and the innocent flow murmur","Know which murmurs always need an echo: any diastolic murmur, and a systolic murmur with symptoms, a thrill or a soft S2"],
  signs:["mr-murmur","ar-murmur","ar-eponyms","valsalva-murmur","handgrip"],sounds:["as","mr","ar","ms","hocm","innocent","mvp","tr","vsd","pda"],maps:["murmurs"],go:[["sounds/compare","Look-alike sounds side by side"],["practice/drill","Sound drills"]],cards:["f:cvs:2","f:cvs:3"],
  trap:"Naming a valve from the site alone: radiation and manoeuvres decide.",pearl:"A systolic murmur that gets louder with Valsalva or on standing from a squat: HOCM.",
  src:"Lembo et al., NEJM 1988 (manoeuvres); McGee 5e, ch 41; ESC valvular guidelines 2021"},
 {id:"heart-failure",t:"The failing heart",aim:"Recognise heart failure at the bedside and say whether the patient is wet, cold or both.",
  master:["Ask for the history clues with the most weight: orthopnoea, paroxysmal nocturnal dyspnoea, previous myocardial infarction","Find the JVP, AJR, S3, displaced apex, crackles and oedema, and know which rule in (S3, JVP, AJR)","Classify the profile: warm or cold (perfusion), wet or dry (congestion)","Use NT-proBNP in primary care: over 2,000 ng/L, specialist assessment within 2 weeks; 400 to 2,000 ng/L, within 6 weeks"],
  signs:["jvp","ajr","s3","crackles","oedema","apex-displaced"],pres:["dysp"],cases:["hf"],scen:["ape"],maps:["heart-failure"],labs:["natriuretic"],cards:["f:cvs:1"],
  trap:"Calling bilateral basal crackles pneumonia in an older patient with a raised JVP.",pearl:"An S3 strongly raises the likelihood of a high filling pressure, but its absence does not exclude heart failure.",
  red:"Cold and wet (hypotension, cold peripheries, confusion, little urine, with pulmonary oedema): cardiogenic shock.",
  src:"Wang et al., JAMA 2005; Nohria et al., J Am Coll Cardiol 2003; NICE NG106 (chronic heart failure)"},
 {id:"heart-chestpain",t:"Chest pain, collapse and palpitations",aim:"Find the four killers and the dangerous faint from the history and the bedside.",
  master:["Name the killers: acute coronary syndrome, aortic dissection, pulmonary embolism, tension pneumothorax, and oesophageal rupture","Weigh the ACS clues: radiation to both arms raises the likelihood most; pleuritic, positional or reproducible pain lowers it but never excludes it","Look for dissection: abrupt severe tearing pain, a pulse deficit or inter-arm difference over 20 mmHg, a new AR murmur, a focal deficit","Find high-risk syncope: on exertion or lying down, palpitations first, a family history of sudden death, structural heart disease, an abnormal ECG","Calculate the HEART score for ED chest pain and the QTc in every faint"],
  pres:["chest","chestwork","sync","palp"],signs:["acs-radiation","chest-wall-tender","add-rs","bp-arms","carotid-upstroke"],tools:["heart","qtc-bazett","qtc-fridericia"],labs:["troponin"],maps:["chest-pain"],cases:["as"],scen:["dissect","as-syncope"],cards:["f:cvs:7"],
  trap:"Being reassured by chest-wall tenderness: it lowers the likelihood of ACS but does not exclude it.",pearl:"Syncope on exertion is cardiac until proved otherwise: AS, HOCM or an arrhythmia.",
  red:"Collapse in a young woman: pregnancy test (ectopic). Collapse with back pain in an older man: AAA.",
  say:"Central chest pain for 40 minutes, radiating to both arms, sweaty; HEART score 6; ECG without ST elevation; first troponin sent.",
  src:"Swap and Nagurney, JAMA 2005; Panju et al., JAMA 1998; Klompas, JAMA 2002; ESC syncope guidelines 2018; Six et al., Neth Heart J 2008 (HEART)"},
 {id:"heart-emerg",t:"Emergencies at the bedside",aim:"Recognise tamponade, endocarditis and acute valve failure clinically.",
  master:["Name Beck's triad (hypotension, raised JVP, quiet heart sounds) and why it is often incomplete","Measure pulsus paradoxus with a cuff: a fall of more than 10 mmHg on inspiration","In fever with a murmur, look for the stigmata of endocarditis and take three sets of blood cultures before antibiotics if the patient is stable","Recognise acute MR or a VSD after an MI: new murmur and shock, usually within the first week","Know that a muffled mechanical valve click means valve thrombosis or failure"],
  signs:["tamponade-signs","pulsus-paradoxus","pericardial-rub","endocarditis-stigmata"],sounds:["muffled","acute-mr","rub","mech-avr"],cases:["tamp"],scen:["tamp","pmi-mr","pmi-vsd","ivdu","mech"],maps:["shock"],cards:["f:cvs:4","f:cvs:5"],
  trap:"Waiting for the full Beck's triad.",pearl:"Fever plus a new murmur is endocarditis until blood cultures say otherwise.",
  src:"Talley and O'Connor 9e; McGee 5e; ESC endocarditis guidelines 2023"}
],
vessels:[
 {id:"vessels-bp",t:"Blood pressure, done properly",aim:"Measure a pressure you would trust.",
  master:["Choose the cuff: the bladder length encircles at least 80% of the arm, and its width is about 40% of the arm circumference","Seat the patient for 5 minutes, back supported, feet flat, arm at heart level, no talking","Measure both arms the first time; if they differ by more than 15 mmHg, repeat, and then use the higher arm","Confirm a raised clinic pressure with ambulatory or home monitoring before diagnosing hypertension","Know what an inter-arm difference means: 15 mmHg or more marks vascular risk; over 20 mmHg with chest pain suggests dissection"],
  signs:["bp-arms"],tools:["map"],
  trap:"A small cuff on a large arm reads falsely high.",pearl:"Chest pain with an inter-arm difference: think aortic dissection.",
  red:"180/120 mmHg or more with papilloedema, retinal haemorrhage, chest pain, confusion or acute kidney injury: same-day specialist assessment.",
  src:"Muntner et al., AHA Scientific Statement, Hypertension 2019; NICE NG136; Clark et al., Lancet 2012"},
 {id:"vessels-arteries",t:"The arteries",aim:"Find and grade peripheral pulses, bruits and the aneurysm.",
  master:["Feel femoral, popliteal, posterior tibial and dorsalis pedis pulses","Calculate and interpret an ABI: under 0.9 means peripheral arterial disease, over 1.4 means stiff arteries","Palpate the aorta for an expansile mass and know who is screened: men at 65"],
  signs:["pedal-pulses","abi","aaa-palp","carotid-bruit","abd-bruit","radio-femoral"],tools:["abi"],cards:["a:neck:car","f:abd:6"],
  trap:"A falsely high ABI in diabetes or renal disease from stiff arteries (over 1.4).",pearl:"Abdominal or back pain, hypotension and a pulsatile mass: ruptured AAA until proven otherwise.",
  src:"NICE CG147 (peripheral arterial disease); Lederle and Simel, JAMA 1999; NHS AAA screening programme"},
 {id:"vessels-coldleg",t:"The cold leg",aim:"Recognise acute limb ischaemia within minutes and grade chronic ischaemia.",
  master:["Name the six Ps: pain, pallor, pulselessness, perishing cold, paraesthesia, paralysis","Treat sensory loss or weakness as a threatened limb: heparin and an emergency vascular referral","Look for the source: atrial fibrillation, a recent MI, an aneurysm, a previous bypass","Perform Buerger's test: pallor on elevation (at under about 20° in severe ischaemia), rubor when the leg hangs down","Recognise chronic limb-threatening ischaemia: rest pain at night relieved by hanging the leg out of bed, ulcers or gangrene"],
  signs:["pedal-pulses","abi","cap-refill","passive-leg-mottling"],tools:["abi"],labs:["lactate"],cards:["f:cvs:8"],
  trap:"Calling a painful, pulseless leg sciatica or a DVT because nobody felt the foot.",pearl:"Paralysis and sensory loss mean hours, not days: give heparin and call the vascular surgeons now.",
  red:"Weakness or numbness in a cold leg; fixed, non-blanching mottling means the limb may already be unsalvageable.",
  say:"Right leg acutely ischaemic for 3 hours: cold and white, no pulses below the femoral, reduced sensation, power intact; in AF.",
  src:"Björck et al., ESVS 2020 acute limb ischaemia guidelines, Eur J Vasc Endovasc Surg 2020; NICE CG147; Talley and O'Connor 9e, peripheral vascular chapter"},
 {id:"vessels-legswell",t:"The swollen leg",aim:"Separate DVT, cellulitis, heart failure and lymphoedema.",
  master:["Score Wells for DVT: likely (2 or more) needs a proximal leg vein scan; unlikely needs a D-dimer first","Use the age-adjusted D-dimer over 50 and know why Homans' sign is abandoned","Grade pitting oedema and look for its cause above the legs: heart, liver, kidney, drugs","Recognise lymphoedema: Stemmer's sign, a skin fold at the base of the second toe that cannot be pinched"],
  signs:["wells-dvt","homans","oedema"],pres:["legswell"],tools:["wells-dvt","age-adjusted-ddimer"],labs:["d-dimer"],cards:["f:derm:15"],
  trap:"Treating bilateral oedema as two DVTs.",pearl:"Bilateral oedema is systemic (heart, liver, kidney, drugs such as amlodipine) until proven otherwise.",
  src:"NICE NG158 (venous thromboembolism, 2020); Righini et al., JAMA 2014 (age-adjusted D-dimer)"},
 {id:"vessels-shock",t:"Shock and fluid responsiveness",aim:"Name the type of shock and decide whether more fluid will help.",
  master:["Sort shock into hypovolaemic, distributive, cardiogenic and obstructive with two questions: warm or cold, JVP high or low?","Read perfusion at the bedside: mottling, capillary refill, the skin temperature gradient, urine output, mental state","Perform a passive leg raise with a real-time measure of output: a rise of about 10% predicts fluid response","Know its limits: raised intra-abdominal pressure and no way of measuring output"],
  signs:["plr","passive-leg-mottling","cap-refill"],maps:["shock"],tools:["map","shock-index"],labs:["lactate"],
  trap:"Giving fluid because the pressure is low without asking if the heart can use it.",pearl:"The passive leg raise is a reversible fluid challenge.",
  src:"Monnet et al., Intensive Care Med 2016; Surviving Sepsis Campaign 2021"}
],
lungs:[
 {id:"lungs-inspect",t:"Inspect and count",aim:"Read work of breathing and pattern before touching.",
  master:["Count the rate for a full minute; judge depth and pattern","Spot paradoxical abdominal movement and accessory muscle use","Measure a peak flow (best of three) and a forced expiratory time"],
  signs:["resp-rate","paradox-abdomen","peak-flow","fet","laryngeal-height","hoover"],go:[["learn/module/resp","The respiratory examination"]],
  trap:"A quiet, tired asthmatic who is about to stop breathing.",pearl:"A silent chest in asthma is life-threatening.",
  src:"BTS/SIGN 158 asthma guideline (2019); McGee 5e, ch 32"},
 {id:"lungs-trachea",t:"The trachea and expansion",aim:"Feel the mediastinum and the movement of each side.",
  master:["Feel the trachea gently in the suprasternal notch","Compare expansion with your thumbs on the back, then the front","Know that tracheal deviation is a late and unreliable sign of tension pneumothorax"],
  signs:["tracheal-deviation","chest-expansion"],
  trap:"Pressing too hard on the trachea.",pearl:"Trachea pushed away from a white-out: a large effusion or mass. Pulled towards a white-out: collapse or pneumonectomy. Pushed away from a black, silent, hyper-resonant side: tension pneumothorax, and do not wait for the trachea.",
  src:"Talley and O'Connor 9e, respiratory chapter; ATLS; Roberts et al., Ann Surg 2015"},
 {id:"lungs-percuss",t:"Percussion",aim:"Hear and feel resonance, dullness and stony dullness.",
  master:["Strike the middle phalanx with a wrist movement, not the elbow","Compare side to side, top to bottom","Percuss diaphragmatic excursion"],
  signs:["percussion-dull","hyperresonance","auscultatory-percussion"],
  trap:"Comparing apices with bases instead of side with side.",pearl:"Stony dullness at a base is effusion until shown otherwise.",
  src:"McGee 5e; Wong et al., JAMA 2009 (effusion signs)"},
 {id:"lungs-sounds",t:"Breath sounds and added sounds",aim:"Hear vesicular, bronchial, crackles, wheeze, stridor and rubs.",
  master:["Recognise bronchial breathing at the periphery","Time crackles: early or late, fine or coarse, and whether they clear with a cough","Tell a monophonic fixed wheeze (one narrowed airway) from polyphonic wheeze","Tell stridor (inspiratory, upper airway) from wheeze"],
  signs:["bronchial-breathing","crackles","wheeze","stridor-sign"],sounds:["vesicular","bronchial","fine-crackles","coarse-crackles","wheeze","rhonchi","stridor","pleural-rub","diminished","silent-chest"],go:[["sounds/map","Lung zones"]],cards:["lz:*","f:resp:3","f:resp:4","f:resp:5","f:resp:6"],
  trap:"Calling transmitted upper airway sounds wheeze.",pearl:"Fine late inspiratory crackles that do not clear with coughing: fibrosis or early oedema.",
  src:"Bohadana et al., NEJM 2014 (lung sounds); McGee 5e"},
 {id:"lungs-voice",t:"The voice through the chest",aim:"Use the voice to confirm consolidation.",
  master:["Test vocal resonance or fremitus, egophony and whispered pectoriloquy","Explain why consolidation conducts sound and fluid does not","Read the patterns: consolidation is dull with bronchial breathing and increased vocal resonance; an effusion is stony dull with reduced breath sounds and resonance; a pneumothorax is hyper-resonant and silent"],
  signs:["fremitus","egophony","whisper"],maps:["pneumonia-vs-effusion-vs-pneumothorax"],cards:["f:resp:0","f:resp:1"],
  trap:"Expecting increased resonance over an effusion.",pearl:"Egophony has one of the highest LR+ of any chest sign for pneumonia.",
  src:"McGee 5e, ch 33"},
 {id:"lungs-pneumonia",t:"Pneumonia, effusion and the PE question",aim:"Turn chest findings into a diagnosis and a severity.",
  master:["Score CURB-65 (CRB-65 outside hospital) and know its limits: the young, the hypoxic and the frail","Use Wells or YEARS with a D-dimer, and PERC only when your gestalt is already low","Think of PE when the chest is clear but the patient is tachypnoeic and hypoxic","Separate consolidation, effusion and pneumothorax from percussion, breath sounds and vocal resonance"],
  signs:["curb65","wells-pe","crackles","percussion-dull"],pres:["cough","dysp"],cases:["pna","eff","copd"],maps:["dyspnoea","pneumonia-vs-effusion-vs-pneumothorax"],tools:["curb65","crb65","wells-pe","perc","years","spesi"],labs:["d-dimer","inflammatory"],cards:["f:resp:7","f:resp:8"],
  trap:"Applying PERC to a patient you already think has a PE.",pearl:"A normal chest examination in a breathless, hypoxic patient is a clue, not a reassurance: think PE.",
  src:"Lim et al., Thorax 2003 (CURB-65); NICE NG138; Kline et al., J Thromb Haemost 2004 (PERC); van der Hulle et al., Lancet 2017 (YEARS)"},
 {id:"lungs-emerg",t:"The breathless emergency",aim:"Recognise life-threatening asthma, tension pneumothorax, anaphylaxis and upper airway obstruction.",
  master:["Grade acute severe asthma: PEF 33 to 50% of best or predicted, rate 25 or more, pulse 110 or more, cannot complete sentences","Grade life-threatening asthma: PEF under 33%, SpO₂ under 92%, silent chest, cyanosis, poor effort, exhaustion, arrhythmia, hypotension, confusion, or a normal PaCO₂","Diagnose tension pneumothorax clinically and decompress in the 4th or 5th intercostal space just anterior to the mid-axillary line","Give IM adrenaline for anaphylaxis: 0.5 mg (500 micrograms) into the anterolateral thigh in adults, repeated after 5 minutes if needed"],
  signs:["tension-ptx","ptx-signs","peak-flow","stridor-sign","paradox-abdomen","tracheal-deviation"],sounds:["silent-chest","absent-breath","stridor","hamman"],scen:["ptx","asthma","anaph","ape"],tools:["aa-gradient"],labs:["blood-gas"],cards:["f:resp:2"],
  trap:"Waiting for an X-ray to diagnose tension pneumothorax.",pearl:"Hypotension, raised JVP, absent breath sounds and hyper-resonance on one side: decompress now.",
  red:"A normal PaCO₂ in a breathless asthmatic is life-threatening; a raised one is near-fatal.",
  src:"BTS/SIGN 158 (2019); ATLS 10th and 11th eds; Resuscitation Council UK, Emergency treatment of anaphylaxis (2021)"}
],
belly:[
 {id:"belly-inspect",t:"Inspect and look for liver disease",aim:"Read the abdomen and the hands before palpating.",
  master:["Expose from the xiphisternum (or nipples for inspection) to the symphysis pubis with the genitalia covered; examine the groin separately, with consent and a chaperone offered","Name the nine regions and what lies beneath each","Find the stigmata of chronic liver disease","Elicit asterixis: arms out, wrists extended, fingers spread, watched for at least 15 seconds"],
  signs:["cirrhosis-signs","asterixis"],tools:["child-pugh","maddrey","meld"],labs:["lfts"],go:[["learn/module/abd","The abdominal examination"]],cards:["a:abdomen:*"],
  trap:"Examining a patient who is not lying flat and relaxed.",pearl:"Asterixis is not specific to the liver: think CO₂ retention and uraemia.",
  src:"Macleod's 15e, ch 12; Talley and O'Connor 9e"},
 {id:"belly-palpate",t:"Palpation that the patient allows",aim:"Palpate painlessly and learn the most from it.",
  master:["Start away from the pain and watch the face","Distinguish voluntary guarding from rigidity","Use the cough test and percussion tenderness instead of rebound"],
  signs:["rebound","cough-test","heel-drop","carnett","rlq-tender"],
  trap:"Digging for rebound: it hurts and adds little over percussion tenderness.",pearl:"Carnett's sign: pain worse when tensing the abdominal wall suggests the wall, not the viscera.",
  src:"McGee 5e, ch 51"},
 {id:"belly-organs",t:"Organs and masses",aim:"Feel liver, spleen, kidneys and the aorta.",
  master:["Palpate from the right iliac fossa upward, in time with breathing","Percuss the liver span","Tell spleen from kidney","Interpret Courvoisier's sign: a palpable, painless gallbladder with jaundice is unlikely to be stones"],
  signs:["liver-palp","spleen-palp","courvoisier","murphy","aaa-palp"],cards:["f:abd:9"],
  trap:"Starting palpation in the right upper quadrant and missing a huge liver.",pearl:"Spleen: moves with respiration, has a notch, you cannot get above it, dull to percussion.",
  src:"Talley and O'Connor 9e; McGee 5e"},
 {id:"belly-ascites",t:"Ascites",aim:"Detect fluid and judge how much.",
  master:["Perform shifting dullness","Know why the fluid wave needs a third hand","Know the bedside causes: portal hypertension, malignancy, heart failure, nephrotic syndrome"],
  signs:["shifting-dullness","fluid-wave","puddle"],cards:["f:abd:8"],
  trap:"Calling ascites from flank fullness alone.",pearl:"Absent flank dullness makes ascites unlikely.",
  src:"Williams and Simel, JAMA 1992; McGee 5e"},
 {id:"belly-acute",t:"The acute abdomen",aim:"Find appendicitis, cholecystitis, peritonitis and torsion at the bedside.",
  master:["Elicit Rovsing, psoas and obturator signs and know their weight","Score Alvarado or AIR: a low score helps rule appendicitis out","Check the hernial orifices and genitalia in every acute abdomen","Suspect testicular torsion with sudden pain, a high-riding testis and no cremasteric reflex; score TWIST, but do not delay surgical review for a scan","Test for pregnancy in every woman of reproductive age with abdominal pain"],
  signs:["rovsing","psoas","obturator","alvarado","hernia-cough","cremasteric","cva","bowel-sounds","cullen"],pres:["abdo","dysuria"],cases:["app","chole"],scen:["boerhaave"],maps:["acute-abdomen"],tools:["alvarado","air","twist"],cards:["f:abd:0","f:abd:1","f:abd:2","f:abd:3","f:abd:4","f:abd:5","f:abd:7"],
  trap:"Missing testicular torsion or an incarcerated hernia because the groin was not examined.",pearl:"Pain out of proportion to the findings, especially with AF: mesenteric ischaemia.",
  red:"Rigidity, shock, pain out of proportion, a pulsatile mass, or a tender irreducible hernia.",
  src:"McGee 5e, ch 51; Ohle et al., BMC Med 2011 (Alvarado); Barbosa et al., J Urol 2013 (TWIST)"},
 {id:"belly-women",t:"Abdominal pain in women and early pregnancy",aim:"Exclude pregnancy first and ectopic pregnancy second.",
  master:["Do a pregnancy test in every woman of reproductive age with abdominal pain, collapse or unexplained vomiting, whatever her contraception or last period","Know the atypical presentations of ectopic pregnancy: diarrhoea, dizziness, shoulder-tip pain, urinary symptoms, no bleeding","Treat a positive test with pain or bleeding and no intrauterine pregnancy on ultrasound as ectopic until proved otherwise","Separate torsion (sudden unilateral pain with vomiting), PID (cervical motion tenderness, discharge, fever) and appendicitis","In shock: two large-bore cannulae, cross-match, and call the gynaecologists"],
  pres:["womabdo"],signs:["cmt","postural","shock-index"],labs:["urinalysis"],
  trap:"Excluding pregnancy because the patient says she cannot be pregnant, or because she has had a period.",pearl:"Shoulder-tip pain or fainting in early pregnancy means blood in the abdomen.",
  red:"Haemodynamic instability, peritonism, shoulder-tip pain or syncope with a positive test.",
  say:"We test everyone of your age with this kind of pain; it is routine, and it tells us which scans and medicines are safe.",
  src:"NICE NG126 (ectopic pregnancy and miscarriage, 2019, updated 2023); RCOG Green-top Guideline 21"},
 {id:"belly-gibleed",t:"The bleeding gut",aim:"Judge how much blood, from where, and who can go home.",
  master:["Separate haematemesis, coffee grounds, melaena and fresh rectal blood","Know what points to an upper source: melaena and a high urea relative to creatinine","Assess for shock and know that the haemoglobin may be normal at first","Score Glasgow–Blatchford: a score of 0 (NICE) or up to 1 (international consensus) identifies low-risk patients for outpatient care","With stigmata of liver disease, treat as variceal: terlipressin and antibiotics before endoscopy"],
  signs:["dre","cirrhosis-signs","postural"],pres:["gibleed"],tools:["gbs","child-pugh"],labs:["fbc","coagulation","u-and-e"],maps:["gi-bleed-and-liver"],
  trap:"Being reassured by a normal first haemoglobin: it takes hours to fall.",pearl:"Melaena on the glove makes an upper GI source very likely; find it before you score Glasgow–Blatchford. Iron and bismuth blacken stool too.",
  src:"NICE CG141 (upper GI bleeding); Srygley et al., JAMA 2012; Barkun et al., Ann Intern Med 2019"},
 {id:"belly-intimate",t:"The intimate examinations",aim:"Perform rectal and pelvic examination when they change management.",
  master:["Explain, consent and offer a chaperone; respect the patient's wish for a same-sex examiner where possible","Know when a DRE adds information: melaena, retention, suspected cauda equina, prostatitis","Recognise cervical motion tenderness and what it suggests: PID or ectopic pregnancy"],
  signs:["dre","cmt"],
  trap:"Doing a DRE that will not change anything.",pearl:"Record the chaperone's name, or that one was offered and declined.",
  src:"GMC, Intimate examinations and chaperones (2013); Macleod's 15e"}
],
neck:[
 {id:"neck-thyroid",t:"The thyroid",aim:"Examine the thyroid from behind and decide what kind of goitre it is.",
  master:["Inspect with a swallow of water and with tongue protrusion","Palpate from behind, then percuss for retrosternal extension","Do Pemberton's manoeuvre","Describe it: diffuse, multinodular or a single nodule"],
  signs:["thyroid-palp","pemberton"],maps:["thyroid"],go:[["learn/module/hn","Head, neck and endocrine"]],cards:["f:hn:0","f:hn:1"],
  trap:"Forgetting the water: a goitre moves on swallowing.",pearl:"A thyroglossal cyst moves with tongue protrusion; a thyroid nodule does not.",
  src:"Talley and O'Connor 9e, endocrine chapter; McGee 5e, ch 24"},
 {id:"neck-status",t:"Thyroid status",aim:"Judge the patient's thyroid function from the hands, eyes and reflexes.",
  master:["Look for tremor, warm moist palms, tachycardia or AF","Look for lid retraction, lid lag and proptosis","Time the relaxation of the ankle reflex"],
  signs:["hyperthyroid-signs","hypothyroid-signs"],labs:["thyroid"],
  trap:"Ascribing tachycardia to anxiety in a thin, tremulous patient.",pearl:"In a thyrotoxic patient, proptosis or other thyroid eye disease points to Graves'; lid retraction and lid lag occur in any thyrotoxicosis.",
  src:"Talley and O'Connor 9e; McGee 5e, ch 24"},
 {id:"neck-nodes",t:"Lymph nodes",aim:"Examine nodes systematically and judge which need a biopsy.",
  master:["Examine all levels of the neck from behind, then the supraclavicular fossae","Describe size, consistency, tenderness, fixity and the territory it drains","Refer on a suspected cancer pathway: an unexplained neck lump at 45 or over, and any node that is hard, fixed, over about 2 cm or persisting beyond about 6 weeks"],
  signs:["lymph-nodes","lymph-supraclav"],cards:["a:neck:*","f:hn:2"],
  trap:"Reassuring about a hard, fixed node because it is painless.",pearl:"A left supraclavicular node points to the abdomen.",
  src:"NICE NG12 (suspected cancer); McGee 5e"},
 {id:"neck-calcium",t:"Calcium",aim:"Elicit the signs of hypocalcaemia and trust the right one.",
  master:["Perform Trousseau's sign safely: cuff above systolic for up to 3 minutes","Know why Chvostek's sign is unreliable: it is present in some healthy people and absent in many hypocalcaemic ones","Correct the calcium for albumin, or measure ionised calcium"],
  signs:["trousseau","chvostek"],labs:["calcium-bone"],tools:["corrected-ca"],
  trap:"Reassurance from a negative Chvostek.",pearl:"After neck surgery, tingling around the mouth is low calcium until measured.",
  src:"Talley and O'Connor 9e; Cooper and Gittoes, BMJ 2008"}
],
senses:[
 {id:"senses-ear",t:"The ear",aim:"See the whole drum and know what you are looking at.",
  master:["Hold the otoscope pen-wise with your hand braced on the head","Straighten the canal: up and back in adults, down and back in infants","Identify the light reflex, the handle of malleus and the pars flaccida"],
  tech:["otoscopy"],signs:["otoscopy"],
  trap:"Missing the pars flaccida, where cholesteatoma hides.",pearl:"A bulging drum is the most useful sign of acute otitis media.",
  src:"Rothman et al., JAMA 2003"},
 {id:"senses-hearing",t:"Hearing",aim:"Separate conductive from sensorineural loss with a fork.",
  master:["Use a 512 Hz fork, struck on your knee or elbow","Perform Weber and Rinne and read them together","Do a whispered voice test"],
  tech:["tuning-fork","whispered-voice"],signs:["rinne-weber","whisper-test"],cards:["f:hn:3"],
  trap:"A 'negative Rinne' from a fork that is too low.",pearl:"Sudden sensorineural hearing loss with a normal drum is an emergency: same-day ENT referral, because steroids work best when started early.",
  src:"Bagai et al., JAMA 2006; ENT UK and NICE CKS (sudden sensorineural hearing loss)"},
 {id:"senses-nose",t:"The nose and sinuses",aim:"Look inside the nose without hurting, and stop it bleeding.",
  master:["Keep the speculum blades in the vestibule and open against the ala, never the septum","Identify the septum, inferior turbinate and Little's area","Stop an anterior nosebleed: lean forward and pinch the soft part of the nose firmly for 10 to 15 minutes"],
  tech:["anterior-rhinoscopy"],signs:["transillumination"],
  trap:"Mistaking a swollen inferior turbinate for a polyp.",pearl:"Polyps are grey, insensate and mobile; turbinates are pink and sensitive. A unilateral polyp or bloody discharge needs ENT review.",
  src:"NICE CKS (epistaxis); Talley and O'Connor 9e"},
 {id:"senses-eye",t:"The eye",aim:"Test vision, see the red reflex and examine the fundus.",
  master:["Measure acuity each eye, with a pinhole if it is reduced","Elicit a red reflex at arm's length","Find the disc by following a vessel towards the nose"],
  tech:["visual-acuity","red-reflex","direct-ophthalmoscopy"],signs:["visual-acuity","fundoscopy"],
  trap:"Calling papilloedema from a single look through a small pupil.",pearl:"Acuity is the vital sign of the eye: record it before anything else.",
  src:"Macleod's 15e, eye chapter"},
 {id:"senses-redeye",t:"The red or painful eye",aim:"Separate conjunctivitis from the red eyes that threaten sight.",
  master:["Look for the danger signs: reduced acuity, photophobia, severe pain, a fixed mid-dilated pupil, a hazy cornea, contact lens wear","Know acute angle-closure glaucoma: pain, halos, vomiting, a hard eye and a mid-dilated pupil","Irrigate a chemical injury immediately and keep going before any assessment","In anyone over 50 with new headache or visual symptoms, ask about jaw claudication and scalp tenderness"],
  signs:["red-eye","visual-acuity","jaw-claudication","temporal-artery"],pres:["redeye"],cards:["f:hn:4","f:hn:5"],
  trap:"Calling every red eye conjunctivitis without checking the acuity.",pearl:"Red eye with pain, reduced vision or photophobia is not conjunctivitis.",
  red:"Suspected giant cell arteritis: start prednisolone the same day and refer urgently; visual loss is an emergency.",
  src:"NICE CKS (red eye); British Society for Rheumatology GCA guideline 2020; Smetana and Shmerling, JAMA 2002"},
 {id:"senses-throat",t:"The throat",aim:"Decide who needs antibiotics for a sore throat, and who needs a surgeon.",
  master:["Score FeverPAIN or Centor and know what each score means for antibiotics","Look for quinsy: trismus, uvula deviation, a hot potato voice","Recognise epiglottitis and deep neck infection: drooling, stridor, sitting forward, unable to swallow saliva"],
  signs:["centor"],pres:["throat"],tools:["centor","feverpain"],cards:["f:hn:6"],
  trap:"Missing epiglottitis because you could not see the throat.",pearl:"Never put a spatula in a child with drooling and stridor.",
  src:"NICE NG84 (sore throat, antimicrobial prescribing); Little et al., BMJ 2013 (FeverPAIN)"}
],
cranial:[
 {id:"cranial-screen",t:"Twelve roads in five minutes",aim:"Screen all twelve cranial nerves in a fixed order and know when to look closer.",
  master:["Run the screen in order: smell, vision and pupils, eye movements, face, hearing, palate, shoulders, tongue","Ask about smell, and test each nostril with a familiar smell after head injury or with parkinsonism; avoid ammonia, which tests V","Know which nerves travel together: III, IV, VI in the cavernous sinus; V, VII, VIII at the cerebellopontine angle; IX, X, XI at the jugular foramen"],
  signs:["visual-acuity","whisper-test"],go:[["learn/cranial","The cranial nerves"]],cards:["cn:*"],
  trap:"Skipping smell: post-traumatic anosmia is common and is often the only sign of a frontal injury.",pearl:"Groups of nerves localise: several adjacent nerves together point to one place.",
  src:"Fuller, Neurological Examination Made Easy 6e; Talley and O'Connor 9e"},
 {id:"cranial-pupils",t:"The pupils",aim:"Find an afferent defect and a Horner's syndrome.",
  master:["Swing a torch two to three seconds per eye in a dim room","Distinguish anisocoria worse in light (parasympathetic) from worse in the dark (sympathetic)","Name Horner's: ptosis, miosis, and sometimes loss of sweating"],
  tech:["swinging-torch"],signs:["rapd","horner"],cards:["cn:II"],
  trap:"Swinging too fast or in a bright room.",pearl:"New Horner's with neck pain is carotid dissection until imaged.",
  src:"Fuller 6e; McGee 5e"},
 {id:"cranial-fields",t:"The fields",aim:"Map a field defect to a place in the visual pathway.",
  master:["Test each quadrant of each eye by confrontation","Localise bitemporal, homonymous and altitudinal defects","Look for neglect with bilateral simultaneous stimuli"],
  tech:["confrontation-fields"],signs:["visual-fields"],
  trap:"Testing both eyes together.",pearl:"Homonymous defect: behind the chiasm. Bitemporal: at it. Altitudinal: the eye itself.",
  src:"Fuller 6e"},
 {id:"cranial-movements",t:"Eye movements",aim:"Find a palsy, an INO, a skew or fatigable weakness.",
  master:["Use the H pattern slowly, asking about double vision and where it is worst","Name III, IV and VI palsies from the position of the eye and the cover test","Recognise an INO: failure of adduction on the side of the lesion with nystagmus of the abducting eye","Look for fatigable ptosis and test it with sustained upgaze or an ice pack (myasthenia)"],
  tech:["eye-movements"],signs:["cn3-pupil","ice-pack"],go:[["learn/cranial","The cranial nerves"]],cards:["cn:III","cn:IV","cn:VI","f:neuro:5"],
  trap:"Missing a pupil-involving third nerve palsy: posterior communicating aneurysm until proved otherwise.",pearl:"A painless, complete, pupil-sparing third nerve palsy in a diabetic is usually microvascular; a partial one is not reassuring: image it.",
  src:"Fuller 6e; Talley and O'Connor 9e"},
 {id:"cranial-face",t:"The face: V and VII",aim:"Test facial sensation and power, and tell central from peripheral facial palsy.",
  master:["Test light touch in V1, V2 and V3, and the corneal reflex (V in, VII out)","Test the masseters and jaw opening: the jaw deviates towards the weak side; a brisk jaw jerk means an upper motor neurone lesion above the pons","Test the forehead: spared in UMN lesions, involved in LMN lesions","In Bell's palsy, look in the ear for vesicles (Ramsay Hunt), give prednisolone within 72 hours, and protect the eye"],
  signs:["facial-palsy"],cards:["cn:V","cn:VII","f:neuro:0","f:hn:7"],
  trap:"Calling a facial palsy Bell's without checking the ear, the parotid and the rest of the neurological examination.",pearl:"Numbness confined to the chin (numb chin syndrome) can be the first sign of metastatic cancer.",
  src:"Fuller 6e; Sullivan et al., NEJM 2007; NICE CKS (Bell's palsy)"},
 {id:"cranial-lower",t:"The lower roads: IX to XII and the bulbar patient",aim:"Examine the palate, swallow, shoulders and tongue, and tell bulbar from pseudobulbar palsy.",
  master:["Watch the palate rise on 'ah': the uvula is pulled away from the weak side","Screen the swallow with a water swallow test, not the gag","Test XI: shrug (trapezius) and head turning against your hand (each sternocleidomastoid turns the head to the opposite side)","Test XII: the protruded tongue deviates towards the weak side; look for wasting and fasciculation with the tongue at rest","Tell bulbar palsy (LMN: wasted, fasciculating tongue, nasal speech) from pseudobulbar palsy (UMN: small stiff tongue, brisk jaw jerk, emotional lability)"],
  signs:["water-swallow","gag"],cards:["cn:IX","cn:X","cn:XI","cn:XII"],
  trap:"Relying on the gag reflex to judge swallowing.",pearl:"The gag reflex is absent in many healthy people and present in many who aspirate.",
  red:"New dysphagia with dysarthria, fatigable weakness or breathlessness: think myasthenic crisis, Guillain-Barré or brainstem stroke.",
  src:"Fuller 6e; Talley and O'Connor 9e; Suiter and Leder, Dysphagia 2008 (water swallow)"},
 {id:"cranial-dizzy",t:"The dizzy patient",aim:"Separate BPPV, vestibular neuritis and stroke.",
  master:["Classify dizziness by timing and trigger, not by the word the patient uses","Perform Dix–Hallpike for triggered episodic vertigo, and treat a posterior canal BPPV with Epley","Perform HINTS only in acute continuous vertigo with nystagmus, and only if you are trained in it","Always test gait and truncal ataxia: inability to walk unaided is a central sign"],
  tech:["dix-hallpike","epley","hints"],signs:["dix-hallpike","epley","hints"],pres:["dizz"],cases:["vert"],maps:["vertigo"],cards:["cn:VIII","f:neuro:7"],
  trap:"Using HINTS in a patient without nystagmus.",pearl:"A normal head impulse in acute continuous vertigo is a red flag for stroke.",
  red:"Vertigo with neck pain or headache, new neurological signs, or inability to walk: central until imaged; do not do head impulses with suspected vertebral dissection.",
  src:"Edlow et al., GRACE-3, Acad Emerg Med 2023; Kattah et al., Stroke 2009; Ohle et al., Acad Emerg Med 2020"}
],
mind:[
 {id:"mind-gcs",t:"The conscious level",aim:"Score GCS precisely and spot the head injury that needs a scan.",
  master:["Score eyes, verbal and motor separately and report the parts (E3 V4 M6)","Use a central painful stimulus (trapezius squeeze or supraorbital pressure) to test localising","Know the NICE indications for CT within 1 hour: GCS under 13 at first assessment or under 15 at 2 hours, signs of skull fracture, a post-traumatic seizure, a focal deficit, more than one vomit","Apply the Canadian CT head rule in adults and PECARN in children"],
  signs:["gcs","ct-head-rule","battle"],pres:["seizure"],tools:["gcs","cchr","pecarn-u2","pecarn-2plus"],
  trap:"Reporting a GCS total without the parts.",pearl:"The motor score carries most of the prognosis.",
  red:"A fall of 2 or more points, a new dilated pupil, or a head injury on an anticoagulant.",
  src:"Teasdale et al., Lancet Neurol 2014; NICE NG232 (head injury, 2023); Stiell et al., Lancet 2001; Kuppermann et al., Lancet 2009"},
 {id:"mind-mental",t:"Speech, mood and the mental state",aim:"Describe speech and mental state precisely and ask about suicide safely.",
  master:["Tell dysphasia (language: naming, repetition, comprehension) from dysarthria (articulation) and dysphonia (voice)","Localise dysphasia: non-fluent (expressive, frontal) or fluent with poor comprehension (receptive, temporal)","Record a mental state examination: appearance and behaviour, speech, mood and affect, thought, perception, cognition, insight","Ask about suicide directly, then plan, intent, means and protective factors, and agree a safety plan","Do not use a risk score or tool to predict suicide or to decide care"],
  pres:["mse"],go:[["learn/frames","History frameworks"]],
  trap:"Labelling risk 'low' from a checklist.",pearl:"Asking directly about suicide does not plant the idea; it is the start of keeping someone safe.",
  red:"A current plan with access to means, recent attempt, hopelessness, command hallucinations, intoxication, or no protective factors.",
  say:"Sometimes when people feel this low they think about ending their life. Have you had thoughts like that?",
  src:"NICE NG225 (self-harm, 2022); Dazzi et al., Psychol Med 2014; Whooley et al., J Gen Intern Med 1997; Fuller 6e (speech)"},
 {id:"mind-power",t:"Tone, power and drift",aim:"Find weakness and say whether it is UMN or LMN.",
  master:["Feel tone at the wrist and knee, and look for clonus","Grade MRC power 0 to 5 with the proximal joint stabilised","Elicit pronator drift with eyes closed, palms up, for 20 to 30 seconds","Say the pattern: UMN weakness is pyramidal (arm extensors, leg flexors); LMN has wasting and fasciculation"],
  tech:["clonus-tone","mrc-power","pronator-drift"],signs:["pronator-drift","clonus"],go:[["learn/module/neuro","The neurological examination"],["learn/myotomes","Myotomes and reflexes"]],cards:["my:*"],
  trap:"Grading power without stabilising the proximal joint.",pearl:"Pronator drift is one of the most sensitive signs of a mild UMN lesion.",
  src:"Fuller 6e; Medical Research Council, Aids to the examination of the peripheral nervous system"},
 {id:"mind-reflexes",t:"Reflexes",aim:"Elicit reflexes every time and interpret asymmetry.",
  master:["Let the hammer fall; reinforce with Jendrassik before calling a reflex absent","Name the root of each reflex: biceps C5-6, supinator C6, triceps C7, knee L3-4, ankle S1","Grade 0 to 4 and say which scale you use: on the NINDS scale 2 is the lower half of normal and 3 the upper half","Elicit plantar responses and Hoffmann's sign"],
  tech:["tendon-reflexes","plantar-response","hoffmann"],signs:["reflexes","babinski","hoffmann"],go:[["learn/myotomes","Myotomes and reflexes"]],cards:["rf:*"],
  trap:"Calling a reflex absent without reinforcement.",pearl:"Asymmetry matters more than briskness.",
  src:"Hallett, Neurology 1993 (NINDS scale); Fuller 6e"},
 {id:"mind-sensation",t:"Sensation",aim:"Map sensory loss to root, nerve, cord or cortex.",
  master:["Test vibration at 128 Hz and joint position, from distal to proximal","Find a sensory level with pinprick and check for sacral sparing","Screen diabetic feet with a 10 g monofilament","Go from abnormal to normal to find the boundary"],
  tech:["vibration-proprioception","pinprick-sensory-level","monofilament","two-point"],signs:["monofilament"],go:[["learn/neuromap","Dermatomes and nerves"]],cards:["dm:*"],
  trap:"Testing sensation from normal to abnormal.",pearl:"A sensory level on the trunk means the cord: image the spine at and above it, urgently.",
  src:"Fuller 6e; NICE NG19 (diabetic foot)"},
 {id:"mind-coord",t:"Coordination and balance",aim:"Separate cerebellar, sensory and vestibular unsteadiness.",
  master:["Perform finger-nose, heel-shin and rapid alternating movements","Look for the cerebellar signs: dysdiadochokinesia, ataxia, nystagmus, intention tremor, slurred speech, hypotonia","Do Romberg properly and know what it tests","Watch tandem gait"],
  tech:["cerebellar-tests","romberg","tandem-gait"],signs:["finger-nose","romberg","tandem"],
  trap:"Calling a positive Romberg cerebellar.",pearl:"Romberg tests proprioception: a cerebellar patient is unsteady with the eyes open too.",
  src:"Fuller 6e; Macleod's 15e"},
 {id:"mind-movement",t:"Tremor and parkinsonism",aim:"Classify a tremor and recognise parkinsonism.",
  master:["Classify a tremor as rest, postural, action or intention","Test bradykinesia by finger tapping: look for slowing and decrement, not just slowness","Feel rigidity at the wrist and enhance it by moving the other hand","Know the drug causes: metoclopramide, prochlorperazine, antipsychotics","Know the features of atypical parkinsonism: early falls, early autonomic failure, vertical gaze palsy, poor levodopa response"],
  signs:["bradykinesia","glabellar"],cards:["f:neuro:6"],
  trap:"Calling it Parkinson's from tremor alone: without bradykinesia it is not parkinsonism.",pearl:"Essential tremor is bilateral, postural and action, often familial and better with alcohol; parkinsonian tremor is asymmetric and at rest.",
  src:"Postuma et al., Mov Disord 2015 (MDS criteria); NICE NG71 (Parkinson's disease)"},
 {id:"mind-stroke",t:"Stroke and localisation",aim:"Recognise stroke, say where the lesion is, and know the clock.",
  master:["Use BE-FAST in the field and ROSIER in the emergency department; check the glucose","Localise from the signs: cortex, internal capsule, brainstem, cord","Know the windows: thrombolysis within 4.5 hours of last known well; thrombectomy within 6 hours, and up to 24 hours when imaging shows salvageable brain","For TIA: aspirin 300 mg at once and specialist assessment within 24 hours; do not use ABCD² to triage"],
  signs:["befast","pronator-drift","facial-palsy"],pres:["weak"],cases:["stroke"],maps:["stroke-localisation","weakness-localisation"],tools:["abcd2"],go:[["learn/localise","Localisation"],["practice/localiser","Localiser cases"]],
  trap:"Calling a posterior circulation stroke 'just vertigo'.",pearl:"Crossed signs (face one side, body the other) point to the brainstem.",
  say:"Last known well 06:40; left face, arm and leg weakness, NIHSS 9, glucose 6.2 mmol/L, not anticoagulated.",
  src:"NICE NG128 (stroke and TIA, 2019, updated 2022); Nor et al., Lancet Neurol 2005 (ROSIER)"},
 {id:"mind-headache",t:"Headache and the meninges",aim:"Find the headache that kills and know what meningism signs can and cannot do.",
  master:["Ask the red flags (SNOOP): systemic illness, neurological signs, sudden onset, older age, change in pattern","Treat a thunderclap headache (maximal within a minute) as subarachnoid haemorrhage; CT within 6 hours of onset is highly sensitive","Apply the Ottawa SAH rule only to alert adults with a new severe headache peaking within an hour","Perform neck stiffness, Kernig and Brudzinski, and know that they are insensitive","Check the fundi for papilloedema"],
  tech:["meningism"],signs:["ottawa-sah","neck-stiffness","kernig","fundoscopy"],pres:["head"],cases:["mening"],maps:["headache-red-flags"],tools:["ottawa-sah"],labs:["csf"],cards:["f:neuro:1","f:neuro:2","f:hn:5"],
  trap:"Using a negative Kernig to exclude meningitis.",pearl:"If you suspect bacterial meningitis, treat first, then investigate.",
  src:"Perry et al., BMJ 2011 and JAMA 2013; Thomas et al., Clin Infect Dis 2002; NICE NG240 (2024)"},
 {id:"mind-functional",t:"Functional signs",aim:"Make a positive diagnosis of functional weakness and explain it kindly.",
  master:["Perform Hoover's sign and the hip abductor sign","Recognise other positive signs: give-way weakness, drift without pronation","Know that functional disorders are common and can coexist with structural disease","Explain the diagnosis as real and treatable"],
  tech:["hoover"],signs:["hoover-functional"],
  trap:"Diagnosing 'functional' only by exclusion, or telling the patient nothing is wrong.",pearl:"Show the patient their own Hoover's sign: it shows that the wiring is intact and the problem is getting the signal through.",
  say:"Your nervous system is not damaged, but it is not working properly. That is real, and it can get better.",
  src:"Stone and Carson, Neurol Clin 2011; Daum et al., J Neurol Neurosurg Psychiatry 2014"}
],
spine:[
 {id:"spine-back",t:"The back in the room",aim:"Sort back pain into mechanical, radicular and serious.",
  master:["Ask the red-flag questions every time: cancer history, fever, IV drug use or immunosuppression, trauma, steroids, age, neurological symptoms","Inspect, palpate and measure lumbar flexion with Schober","Know that most back pain needs no imaging (NICE NG59)"],
  signs:["schober","si-cluster"],pres:["back"],maps:["back-pain"],go:[["learn/region/spine","Neck and back"]],cards:["a:back:*","f:msk:4","f:msk:5"],
  trap:"Scanning every back.",pearl:"A history of cancer, fever with IV drug use or immunosuppression, or older age with steroids: image. Night pain alone is not enough.",
  src:"Downie et al., BMJ 2013; NICE NG59 (low back pain and sciatica)"},
 {id:"spine-root",t:"The trapped root",aim:"Find which root, and how badly.",
  master:["Perform SLR, crossed SLR and the femoral stretch test","Screen L4, L5 and S1 by power, reflex and sensation","Tell L5 radiculopathy from common peroneal palsy: L5 also weakens inversion and hip abduction"],
  signs:["slr","crossed-slr","femoral-stretch","lumbar-roots"],go:[["learn/rootnerve","Root or nerve?"]],cards:["rn:0","rn:4","my:L4","my:L5","my:S1","rf:6","rf:7"],
  trap:"Calling foot drop L5 without checking inversion and hip abduction.",pearl:"L5 weakness spares the ankle reflex; S1 loses it.",
  src:"Cochrane review, van der Windt et al. 2010 (SLR); Fuller 6e"},
 {id:"spine-cauda",t:"Cauda equina",aim:"Never miss it.",
  master:["Ask about saddle sensation, bladder, bowel and sexual function in every sciatica","Examine saddle sensation and anal tone when in doubt","Arrange emergency MRI for suspected cauda equina; do not wait for retention"],
  signs:["cauda"],cards:["f:msk:3","rf:9"],
  trap:"Waiting for retention: by then function may not return.",pearl:"Bilateral sciatica is cauda equina until proved otherwise.",
  say:"If you notice numbness between your legs, or any change in passing urine or stool, come to the emergency department at once.",
  src:"GIRFT national suspected cauda equina pathway (2023); NICE NG59"},
 {id:"spine-neck",t:"The neck",aim:"Clear the cervical spine and find a cervical radiculopathy.",
  master:["Apply the Canadian C-spine rule or NEXUS","Perform Spurling's test and the upper limb tension test","Map the root: C5 shoulder abduction and biceps jerk, C6 wrist extension and supinator, C7 triceps"],
  signs:["c-spine-rule","spurling","ultt"],tools:["ccsr","nexus"],
  trap:"Rotating the neck of a patient who should be immobilised.",pearl:"Age 65 or over, a dangerous mechanism or paraesthesia in the limbs: image.",
  src:"Stiell et al., JAMA 2001 and NEJM 2003; Hoffman et al., NEJM 2000 (NEXUS)"},
 {id:"spine-distress",t:"Interpreting distress",aim:"Recognise psychosocial overlay without accusing.",
  master:["Elicit Waddell signs and interpret them as distress, not malingering","Ask about the yellow flags: fear-avoidance, low mood, beliefs about harm, work problems","Use STarT Back or similar to stratify care"],
  signs:["waddell"],
  trap:"Writing 'malingering' on the basis of Waddell signs.",pearl:"In occupational assessment, function and the patient's own goals matter more than signs.",
  src:"Waddell et al., Spine 1980; Fishbain et al., Pain Med 2003; Hill et al., Lancet 2011 (STarT Back)"}
],
arm:[
 {id:"arm-shoulder",t:"The shoulder",aim:"Separate cuff, impingement, instability, ACJ and frozen shoulder.",
  master:["Assess active and passive movement first","Test supraspinatus, infraspinatus and subscapularis separately","Know which tests are sensitive and which are specific"],
  signs:["painful-arc","drop-arm","er-lag","empty-can","lift-off","hawkins","neer","apprehension","cross-body","speed","frozen"],maps:["shoulder-pain"],go:[["learn/region/shoulder","Shoulder"]],cards:["f:msk:2","rn:6"],
  trap:"Calling a frozen shoulder a cuff tear: loss of passive external rotation is the key.",pearl:"Painful arc, drop arm and external rotation weakness together strongly suggest a full-thickness tear.",
  src:"Hermans et al., JAMA 2013; Park et al., J Bone Joint Surg Am 2005"},
 {id:"arm-elbow",t:"The elbow",aim:"Rule out a fracture and find tendinopathy.",
  master:["Use the elbow extension test after trauma","Elicit Cozen's test","Know that lateral elbow pain is common in manual and repetitive work"],
  signs:["elbow-ext","cozen"],go:[["learn/region/elbow","Elbow"]],
  trap:"X-raying every elbow.",pearl:"Full extension after trauma makes a significant fracture unlikely in adults.",
  src:"Appelboam et al., BMJ 2008"},
 {id:"arm-wrist",t:"The wrist and the scaphoid",aim:"Never miss a scaphoid fracture.",
  master:["Press the snuffbox and the tubercle, and compress the thumb along its axis","Perform Finkelstein's test","Arrange MRI when a scaphoid fracture is suspected and the X-ray is normal"],
  signs:["scaphoid","finkelstein","thumb-grind"],go:[["learn/region/wrist","Wrist and hand"]],cards:["f:msk:7"],
  trap:"A normal first X-ray does not exclude a scaphoid fracture.",pearl:"Snuffbox tenderness after a fall: immobilise and image again or arrange MRI.",
  src:"NICE NG38 (non-complex fractures)"},
 {id:"arm-nerves",t:"The nerves of the hand",aim:"Test median, ulnar and radial nerves quickly and accurately.",
  master:["Test thenar power (abductor pollicis brevis) and median sensation","Perform Tinel, Phalen and Durkan","Perform Froment's sign for the ulnar nerve","Test wrist and finger extension for the radial nerve"],
  tech:["tinel","phalen-durkan","froment","mrc-power"],signs:["tinel-wrist","phalen","flick","cts-hypalgesia","froment"],go:[["learn/rootnerve","Root or nerve?"]],cards:["rn:1","rn:2","rn:3","f:neuro:8"],
  trap:"Relying on Tinel alone.",pearl:"Hypalgesia in the median territory and thenar weakness are more useful than Tinel or Phalen.",
  src:"D'Arcy and McGee, JAMA 2000"},
 {id:"arm-tendons",t:"The tendons and the infected finger",aim:"Test every flexor tendon after a cut and recognise flexor sheath infection.",
  master:["Isolate FDS and FDP for each finger","Recognise Kanavel's signs: a finger held flexed, fusiform swelling, tenderness along the sheath, pain on passive extension","Treat any wound over a knuckle from a punch as a human bite"],
  signs:["fdp-fds"],
  trap:"Missing a partial tendon injury because the finger still moves.",pearl:"Pain on resisted flexion after a cut means a partial division until explored.",
  red:"Kanavel's signs or a fight bite: same-day hand surgery review.",
  src:"Kanavel, Infections of the Hand (1912); Talley and O'Connor 9e, hand chapter"}
],
leg:[
 {id:"leg-gait",t:"The walk",aim:"Name the gait and map it to the lesion.",
  master:["Watch the patient walk at least 10 metres, turn and come back, with legs and arms visible","Name the gaits: antalgic, Trendelenburg, high-stepping, spastic or circumducting, cerebellar ataxic, sensory ataxic, parkinsonian, waddling, functional","Map each one: high-stepping is foot drop (L5 or common peroneal); waddling is proximal myopathy or bilateral hip disease","Add heel walking (L5) and toe walking (S1), tandem gait, and Romberg"],
  tech:["tandem-gait","romberg"],signs:["trendelenburg","tandem","romberg","gals","bradykinesia"],cards:["f:neuro:9","rn:0"],
  trap:"Watching only a few steps in a cramped cubicle.",pearl:"Trendelenburg: standing on the weak side, the opposite side of the pelvis drops.",
  red:"A gait disorder with urinary incontinence and cognitive decline: think normal pressure hydrocephalus, one of the few reversible dementias.",
  say:"Antalgic gait with a short stance phase on the right; normal arm swing; turns without difficulty; tandem normal.",
  src:"Fuller 6e; Pirker and Katzenschlager, Wien Klin Wochenschr 2017"},
 {id:"leg-hip",t:"The hip",aim:"Separate hip joint, impingement and referred pain.",
  master:["Examine passive rotation with the hip flexed to 90°","Perform FADIR and the log roll","Perform the Trendelenburg test","Remember the knee: hip disease often presents as knee pain"],
  signs:["fadir","hip-oa","log-roll","trendelenburg","patellar-pubic"],go:[["learn/region/hip","Hip"]],cards:["f:msk:9"],
  trap:"Missing a hip fracture because the patient can walk.",pearl:"Loss of internal rotation is the earliest sign of hip OA.",
  red:"A painful hip after a fall with a normal X-ray: MRI if a fracture is still suspected.",
  src:"Sutlive et al., J Orthop Sports Phys Ther 2008; NICE CG124 (hip fracture)"},
 {id:"leg-knee",t:"The knee after injury",aim:"Find effusion, ligament and meniscal injury, and decide on an X-ray.",
  master:["Detect effusion with the bulge sign and patellar tap","Perform Lachman, anterior drawer, pivot shift and posterior sag","Apply the Ottawa knee rule"],
  signs:["knee-effusion","lachman","ant-drawer-knee","pivot-shift","post-drawer","valgus-stress","ottawa-knee"],cases:["acl"],maps:["knee-injury"],tools:["ottawa-knee","pittsburgh-knee"],go:[["learn/region/knee","Knee"]],cards:["f:msk:0"],
  trap:"Calling an ACL intact from a negative anterior drawer in a guarded knee.",pearl:"Lachman is the most accurate ACL test; pivot shift is the most specific.",
  src:"Benjaminse et al., J Orthop Sports Phys Ther 2006; Stiell et al., JAMA 1997"},
 {id:"leg-meniscus",t:"The meniscus and patella",aim:"Find meniscal tears and patellar instability.",
  master:["Perform McMurray, Thessaly and joint-line tenderness","Perform patellar apprehension","Ask about locking and giving way"],
  signs:["mcmurray","thessaly","joint-line","patellar-app"],
  trap:"Over-calling a meniscal tear from joint-line tenderness alone.",pearl:"Combine tests: a single meniscal test is weak.",
  src:"Hegedus et al., J Orthop Sports Phys Ther 2007"},
 {id:"leg-ankle",t:"The ankle and foot",aim:"X-ray only those who need it and never miss an Achilles rupture.",
  master:["Apply the Ottawa ankle and foot rules","Perform Thompson's test","Test the syndesmosis and the plantar fascia"],
  signs:["ottawa-ankle","thompson","ankle-drawer","squeeze","windlass","mulder"],tools:["ottawa-ankle"],go:[["learn/region/ankle","Ankle and foot"]],cards:["f:msk:8"],
  trap:"Missing an Achilles rupture because the patient can plantarflex.",pearl:"Thompson's test: no plantarflexion on calf squeeze means rupture.",
  src:"Bachmann et al., BMJ 2003; Maffulli, Am J Sports Med 1998"},
 {id:"leg-hotjoint",t:"The hot joint",aim:"Treat a single hot joint as septic until proved otherwise.",
  master:["Aspirate before antibiotics when possible: Gram stain, culture and crystals","Know that crystals in the fluid do not exclude infection","Use the Kocher criteria in a child with a painful hip","Refer a hot prosthetic joint to orthopaedics without aspirating it yourself"],
  pres:["joint"],tools:["kocher"],labs:["inflammatory"],cards:["f:msk:1"],
  trap:"Calling it gout without aspirating.",pearl:"A septic joint destroys cartilage within days.",
  src:"Coakley et al., BSR/BOA guideline, Rheumatology 2006; Kocher et al., J Bone Joint Surg Am 1999"},
 {id:"leg-compartment",t:"The tight compartment",aim:"Recognise acute compartment syndrome before the pulses go.",
  master:["Know who gets it: tibial and forearm fractures, crush injury, reperfusion, tight casts, long immobility, anticoagulation","Find the early signs: pain out of proportion to the injury and pain on passive stretch of the muscles in the compartment","Know that pulses and capillary refill are usually normal until late","Act at once: split the cast and dressing to the skin, keep the limb at heart level, and call orthopaedics for fasciotomy","Measure compartment pressure when the patient cannot report pain: a pressure difference (diastolic minus compartment) under 30 mmHg supports the diagnosis"],
  pres:["trauma"],signs:["compartment","pedal-pulses","cap-refill"],
  trap:"Being reassured by a palpable pulse.",pearl:"A rising need for analgesia after a fracture is compartment syndrome until shown otherwise.",
  red:"Sedated, intubated or intoxicated patients cannot tell you: measure the pressure.",
  src:"BOAST 10, Diagnosis and management of compartment syndrome of the limbs (BOA 2016); McQueen and Court-Brown, J Bone Joint Surg Br 1996"}
],
skin:[
 {id:"skin-describe",t:"Describing a lesion",aim:"Describe any rash so that a dermatologist can picture it.",
  master:["Name the primary lesion: macule, papule, plaque, vesicle, bulla, pustule, nodule, wheal","Add the secondary change: scale, crust, erosion, ulcer, lichenification","Add colour, shape, configuration and distribution","Use diascopy to see blanching"],
  signs:["diascopy"],maps:["the-rash-approach"],go:[["learn/dmorph","The words of the skin"],["learn/describe","Describe like a dermatologist"],["practice/describe","Describe it (practice)"]],cards:["dv:*"],
  trap:"Calling everything 'erythematous rash'.",pearl:"Describe first; the description often suggests the name.",
  say:"Multiple well-demarcated salmon-pink plaques with silvery scale on the extensor elbows and knees.",
  src:"Bolognia, Dermatology 4e; British Association of Dermatologists, dermatology glossary"},
 {id:"skin-signs",t:"Signs that help name it",aim:"Use bedside signs to separate look-alikes.",
  master:["Elicit Nikolsky's sign safely","Know Auspitz and Koebner","Use Wood's lamp"],
  signs:["nikolsky","auspitz","koebner","woods"],pres:["rash"],go:[["learn/datlas","Skin atlas"]],cards:["f:derm:0","f:derm:1","f:derm:2","f:derm:3","f:derm:9","f:derm:12","f:derm:13","f:derm:14"],
  trap:"Rubbing hard enough to create a blister.",pearl:"A positive Nikolsky with mucosal involvement: think SJS/TEN or pemphigus.",
  src:"Bolognia, Dermatology 4e"},
 {id:"skin-pigmented",t:"Pigmented lesions",aim:"Decide which mole needs urgent referral.",
  master:["Apply ABCDE and the weighted 7-point checklist: change in size, shape or colour score 2 each; diameter 7 mm or more, inflammation, oozing and altered sensation score 1 each; 3 or more means refer","Use dermoscopy to look for an atypical network","Know the features of BCC and SCC as well as melanoma"],
  signs:["abcde","dermoscopy"],maps:["pigmented-lesion"],tools:["glasgow-7"],cards:["dc:melanoma","dc:naevus","dc:sk","dc:bcc","dc:scc","dc:ak","f:derm:10","f:derm:11"],
  trap:"Reassuring a changing lesion because it is small.",pearl:"Change is the single most important feature.",
  src:"NICE NG12 and NG14; MacKie, Glasgow 7-point checklist (BMJ 1990)"},
 {id:"skin-redleg",t:"The red leg",aim:"Tell cellulitis from its mimics and spot the leg that is dying.",
  master:["Know that cellulitis is almost always unilateral; bilateral red legs are usually venous stasis dermatitis, lipodermatosclerosis or contact dermatitis","Mark the margin and look for the portal of entry, such as tinea between the toes","Exclude DVT with Wells and ultrasound when the leg is swollen","Recognise necrotising fasciitis: pain out of proportion, rapid spread, bullae, crepitus, numb skin, systemic illness"],
  signs:["oedema","wells-dvt"],pres:["legswell"],tools:["lrinec"],cards:["dc:cellulitis","f:derm:15","f:derm:8"],
  trap:"Treating bilateral 'cellulitis' with week after week of antibiotics.",pearl:"About 3 in 10 patients admitted with cellulitis have something else, most often venous stasis dermatitis.",
  src:"Weng et al., JAMA Dermatol 2017; NICE NG141 (cellulitis and erysipelas, 2019)"},
 {id:"skin-kill",t:"Skin that can kill",aim:"Recognise the dermatological emergencies.",
  master:["Recognise SJS/TEN: painful skin, dusky macules, blisters and mucosal erosions after a new drug; stop the drug and score SCORTEN","Recognise DRESS: rash, fever, facial swelling, eosinophilia and organ involvement weeks after starting a drug","Use LRINEC to rule in necrotising fasciitis, never to rule it out","Recognise erythroderma (over 90% of the skin red) and the non-blanching rash of meningococcal sepsis and vasculitis"],
  signs:["nikolsky","purpura-glass"],tools:["scorten","lrinec"],go:[["learn/demerg","Skin that can kill"]],cards:["dc:sjs","dc:necfasc","dc:meningococcal","dc:vasculitis","dc:pemphigus","dc:bp","f:derm:4","f:derm:5","f:derm:6","f:derm:7","f:derm:8"],
  trap:"Treating pain out of proportion to a red leg as cellulitis, or being reassured by a low LRINEC.",pearl:"Severe pain, rapid spread and systemic illness: necrotising fasciitis. Call the surgeons.",
  red:"Mucosal erosions with skin pain, skin that slides off, or pain out of proportion: same-day specialist care.",
  src:"Fernando et al., Ann Surg 2019 (LRINEC accuracy); Bastuji-Garin et al., J Invest Dermatol 2000 (SCORTEN); British Association of Dermatologists SJS/TEN guideline 2016"}
]};
